    // 1. Input Validation
    if (!wo_input.enable || wo_input.wheel_count != 4 || wo_input.wheels == NULL) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    // Check threshold ordering and positivity
    if (!isfinite(wo_config.release_rad_s) || !isfinite(wo_config.warn_rad_s) || 
        !isfinite(wo_config.trip_rad_s) || !isfinite(wo_config.derate_torque_nm) || 
        !isfinite(wo_config.brake_torque_nm) || !isfinite(wo_config.torque_slew_nm_per_cycle) || 
        !isfinite(wo_config.dt_s)) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    if (wo_config.release_rad_s < 0.0 || wo_config.warn_rad_s < 0.0 || wo_config.trip_rad_s < 0.0 ||
        wo_config.derate_torque_nm <= 0.0 || wo_config.brake_torque_nm <= 0.0 ||
        wo_config.torque_slew_nm_per_cycle <= 0.0 || wo_config.dt_s <= 0.0) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    if (wo_config.release_rad_s >= wo_config.warn_rad_s || wo_config.warn_rad_s >= wo_config.trip_rad_s) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    if (wo_config.release_cycles < 1 || wo_config.release_cycles > 100 ||
        wo_config.minimum_brake_cycles < 1 || wo_config.minimum_brake_cycles > 100 ||
        wo_config.cooldown_cycles < 1 || wo_config.cooldown_cycles > 100) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    if (wo_config.brake_torque_nm < wo_config.derate_torque_nm) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    // Validate wheel telemetry and compute momentum
    adcs_vec3_t momentum;
    adcs_status_t stat = adcs_wheel_momentum(wo_input.wheels, wo_input.wheel_count, &momentum);
    if (stat != ADCS_OK || !adcs_is_finite_vec3(&momentum)) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    double mom_norm = adcs_vec3_norm(&momentum);
    if (!isfinite(mom_norm)) {
        wo_state.mode = WO_FAULT;
        goto fault_output;
    }

    // Calculate max absolute speed across all 4 wheels
    double max_abs_speed = 0.0;
    for (int i = 0; i < 4; i++) {
        double s = fabs(wo_input.wheels[i].speed_rad_s);
        if (s > max_abs_speed) max_abs_speed = s;
    }

    // 2. Mode Transitions
    wo_mode_t prev_mode = wo_state.mode;

    if (prev_mode == WO_NORMAL) {
        if (max_abs_speed >= wo_config.trip_rad_s) {
            wo_state.mode = WO_BRAKE;
            wo_state.elapsed = 0;
            wo_state.clean = 0;
        } else if (max_abs_speed >= wo_config.warn_rad_s) {
            wo_state.mode = WO_DERATE;
            wo_state.elapsed = 0;
            wo_state.clean = 0;
        }
    } else if (prev_mode == WO_DERATE) {
        if (max_abs_speed >= wo_config.trip_rad_s) {
            wo_state.mode = WO_BRAKE;
            wo_state.elapsed = 0;
            wo_state.clean = 0;
        } else {
            if (max_abs_speed <= wo_config.release_rad_s) {
                wo_state.clean++;
                if (wo_state.clean >= wo_config.release_cycles) {
                    wo_state.mode = WO_NORMAL;
                    wo_state.elapsed = 0;
                }
            } else {
                wo_state.clean = 0;
            }
        }
    } else if (prev_mode == WO_BRAKE) {
        wo_state.elapsed++;
        if (wo_state.elapsed >= wo_config.minimum_brake_cycles) {
            if (max_abs_speed <= wo_config.release_rad_s) {
                wo_state.clean++;
                if (wo_state.clean >= wo_config.release_cycles) {
                    wo_state.mode = WO_COOLDOWN;
                    wo_state.elapsed = 0;
                }
            } else {
                wo_state.clean = 0;
            }
        }
    } else if (prev_mode == WO_COOLDOWN) {
        wo_state.elapsed++;
        if (max_abs_speed >= wo_config.trip_rad_s) {
            wo_state.mode = WO_BRAKE;
            wo_state.elapsed = 0;
            wo_state.clean = 0;
        } else if (wo_state.elapsed >= wo_config.cooldown_cycles) {
            wo_state.mode = WO_NORMAL;
            wo_state.elapsed = 0;
        }
    }

    // 3. Torque Calculation per wheel
    double target_torque[4] = {0};
    for (int i = 0; i < 4; i++) {
        double speed = wo_input.wheels[i].speed_rad_s;
        double abs_speed = fabs(speed);

        if (wo_state.mode == WO_DERATE) {
            if (abs_speed > wo_config.release_rad_s) {
                double ratio = (abs_speed - wo_config.release_rad_s) / (wo_config.trip_rad_s - wo_config.release_rad_s);
                double t_mag = wo_config.derate_torque_nm * ratio;
                target_torque[i] = -copysign(t_mag, speed);
            } else {
                target_torque[i] = 0.0;
            }
        } else if (wo_state.mode == WO_BRAKE) {
            if (abs_speed > FLT64_ZERO) {
                target_torque[i] = -copysign(wo_config.brake_torque_nm, speed);
            } else {
                target_torque[i] = 0.0;
            }
        } else {
            // NORMAL, COOLDOWN, FAULT
            target_torque[i] = 0.0;
        }
    }

    // 4. Slew Rate Limiting
    unint32 limited_mask = 0;
    double current_torque[4];
    for (int i = 0; i < 4; i++) {
        current_torque[i] = target_torque[i];
        double diff = current_torque[i] - wo_state.previous_wheel_torque_nm[i];
        if (fabs(diff) > wo_config.torque_slew_nm_per_cycle) {
            current_torque[i] = wo_state.previous_wheel_torque_nm[i] + copysign(wo_config.torque_slew_nm_per_cycle, diff);
            limited_mask |= (unint32)(1U << i);
        }
    }

    // 5. Power and Energy Calculation
    double total_power = 0.0;
    for (int i = 0; i < 4; i++) {
        double speed = wo_input.wheels[i].speed_rad_s;
        double t = current_torque[i];
        double p = t * speed; 
        // Dissipative power is -p. Energy accumulates -p * dt.
        total_power += (-p);
    }
    wo_state.dissipated_energy_j += (-total_power) * wo_config.dt_s;

    // 6. Update State and Fill Output
    for (int i = 0; i < 4; i++) {
        wo_state.previous_wheel_torque_nm[i] = current_torque[i];
    }

    wo_output.mode = wo_state.mode;
    wo_output.clean = wo_state.clean;
    wo_output.elapsed = wo_state.elapsed;
    wo_output.limited_mask = limited_mask;
    for(int i=0; i<4; i++) wo_output.wheel_torque_nm[i] = current_torque[i];
    wo_output.maximum_speed_rad_s = max_abs_speed;
    wo_output.brake_power_w = total_power;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
    wo_output.momentum_norm_nms = mom_norm;
    wo_output.momentum_nms = momentum;

    return;

fault_output:
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.limited_mask = 0;
    for(int i=0; i<4; i++) wo_output.wheel_torque_nm[i] = 0.0;
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    wo_output.dissipated_energy_j = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm_nms = 0.0;

