// 1. Input Validation
if (!wo_input.enable || wo_input.wheel_count != 4U) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.limited_mask = 0U;
    for (int i = 0; i < 4; i++) wo_output.wheel_torque_nm[i] = 0.0;
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
    wo_output.momentum_norm_nms = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0};
    return;
}

const adcs_wheel_t *wheels = wo_input.wheels;
double rel = wo_config.release_rad_s;
double wrn = wo_config.warn_rad_s;
double trp = wo_config.trip_rad_s;
double dtnm = wo_config.derate_torque_nm;
double btnm = wo_config.brake_torque_nm;
double slew = wo_config.torque_slew_nm_per_cycle;
double dt = wo_config.dt_s;
uint32_t rel_cyc = wo_config.release_cycles;
uint32_t min_brk_cyc = wo_config.minimum_brake_cycles;
uint32_t cool_cyc = wo_config.cooldown_cycles;

int is_valid = 1;

if (!(rel >= 0.0 && rel < wrn && wrn < trp)) is_valid = 0;
if (!(isfinite(dtnm) && dtnm > 0.0 && isfinite(btnm) && btnm > 0.0 &&
      isfinite(slew) && slew > 0.0 && isfinite(dt) && dt > 0.0)) is_valid = 0;
if (!(rel_cyc >= 1 && rel_cyc <= 100 && min_brk_cyc >= 1 && min_brk_cyc <= 100 &&
      cool_cyc >= 1 && cool_cyc <= 100)) is_valid = 0;
for (int i = 0; i < 4; i++) {
    if (!isfinite(wheels[i].inertia_kg_m2) || !isfinite(wheels[i].speed_rad_s) ||
        !adcs_is_finite_vec3(&wheels[i].axis_body)) {
        is_valid = 0;
        break;
    }
    if (wheels[i].inertia_kg_m2 <= 0.0) {
        is_valid = 0;
        break;
    }
}
if (btnm < dtnm) is_valid = 0;

adcs_vec3_t mom;
if (is_valid && (adcs_wheel_momentum(wheels, 4, &mom) != ADCS_OK || !adcs_is_finite_vec3(&mom))) {
    is_valid = 0;
}
double mom_norm = 0.0;
if (is_valid) {
    mom_norm = adcs_vec3_norm(&mom);
    if (!isfinite(mom_norm)) is_valid = 0;
}

double max_abs_speed = 0.0;
for (int i = 0; i < 4; i++) {
    double s = fabs(wheels[i].speed_rad_s);
    if (s > max_abs_speed) max_abs_speed = s;
}

wo_mode_t next_mode = wo_state.mode;
if (next_mode != wo_state.mode) {
    wo_state.clean = 0;
}

switch (wo_state.mode) {
    case WO_NORMAL:
        if (max_abs_speed >= trp) {
            next_mode = WO_BRAKE;
            wo_state.elapsed = 0;
        } else if (max_abs_speed >= wrn) {
            next_mode = WO_DERATE;
            wo_state.elapsed = 0;
        } else {
            next_mode = WO_NORMAL;
        }
        break;
    case WO_DERATE:
        if (max_abs_speed >= trp) {
            next_mode = WO_BRAKE;
            wo_state.elapsed = 0;
        } else {
            if (max_abs_speed <= rel) {
                wo_state.clean++;
            } else {
                wo_state.clean = 0;
            }
            if (wo_state.clean >= rel_cyc) {
                next_mode = WO_NORMAL;
            } else {
                next_mode = WO_DERATE;
            }
        }
        break;
    case WO_BRAKE:
        if (max_abs_speed >= trp) {
            wo_state.elapsed = 0;
        } else {
            if (wo_state.elapsed >= min_brk_cyc) {
                if (max_abs_speed <= rel) {
                    wo_state.clean++;
                } else {
                    wo_state.clean = 0;
                }
                if (wo_state.clean >= rel_cyc) {
                    next_mode = WO_COOLDOWN;
                    wo_state.elapsed = 0;
                } else {
                    next_mode = WO_BRAKE;
                }
            } else {
                wo_state.elapsed++;
                next_mode = WO_BRAKE;
            }
        }
        break;
    case WO_COOLDOWN:
        if (max_abs_speed >= trp) {
            next_mode = WO_BRAKE;
            wo_state.elapsed = 0;
        } else {
            wo_state.elapsed++;
            if (wo_state.elapsed >= cool_cyc) {
                next_mode = WO_NORMAL;
            } else {
                next_mode = WO_COOLDOWN;
            }
        }
        break;
    case WO_FAULT:
        next_mode = WO_FAULT;
        break;
    default:
        next_mode = WO_FAULT;
        break;
}

wo_state.mode = next_mode;

double torque_limited[4];
uint32_t limited_mask = 0U;
double total_mech_power = 0.0;

for (int i = 0; i < 4; i++) {
    double speed = wheels[i].speed_rad_s;
    double abs_speed = fabs(speed);
    double prev_torque = wo_state.previous_wheel_torque_nm[i];
    double target_torque = 0.0;

    if (next_mode == WO_NORMAL || next_mode == WO_COOLDOWN) {
        target_torque = 0.0;
    } else if (next_mode == WO_DERATE) {
        double excess = abs_speed - rel;
        double mag = 0.0;
        if (excess > 0.0) {
            double ratio = excess / (trp - rel);
            mag = dtnm * ratio;
            if (mag > dtnm) mag = dtnm;
        }
        if (speed > 0.0) target_torque = -mag;
        else if (speed < 0.0) target_torque = mag;
        else target_torque = 0.0;
    } else if (next_mode == WO_BRAKE) {
        if (speed == 0.0) {
            target_torque = 0.0;
        } else {
            double mag = btnm;
            if (speed > 0.0) target_torque = -mag;
            else target_torque = mag;
        }
    } else {
        target_torque = 0.0;
    }

    double delta = target_torque - prev_torque;
    double max_delta = slew * dt;

    if (delta > max_delta) {
        torque_limited[i] = prev_torque + max_delta;
        limited_mask |= (uint32_t)(1U << i);
    } else if (delta < -max_delta) {
        torque_limited[i] = prev_torque - max_delta;
        limited_mask |= (uint32_t)(1U << i);
    } else {
        torque_limited[i] = target_torque;
    }

    total_mech_power += torque_limited[i] * speed;
    wo_state.previous_wheel_torque_nm[i] = torque_limited[i];
}

wo_state.dissipated_energy_j += -total_mech_power * dt;
double dissipative_power = -total_mech_power;

wo_output.mode = next_mode;
wo_output.limited_mask = limited_mask;
for (int i = 0; i < 4; i++) {
    wo_output.wheel_torque_nm[i] = torque_limited[i];
}
wo_output.maximum_speed_rad_s = max_abs_speed;
wo_output.brake_power_w = dissipative_power;
wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
wo_output.momentum_norm_nms = mom_norm;
wo_output.momentum_nms = mom;

if (!is_valid) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.limited_mask = 0U;
    for (int i = 0; i < 4; i++) {
        wo_output.wheel_torque_nm[i] = 0.0;
        wo_state.previous_wheel_torque_nm[i] = 0.0;
    }
    wo_output.maximum_speed_rad_s = 0.0;
    wo_output.brake_power_w = 0.0;
    wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
    wo_output.momentum_norm_nms = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0};
    return;
}
